mapper.select:
SELECT *
FROM fabric_management
WHERE fb_type IN (
  SELECT fc_ct_name
  FROM fabric_category
  WHERE fc_ct_name = #{fc_ct_name}
);

select po_name, po_extra_price  from customer_choice_option cco 
inner join product_option po on po.po_id_pk = cco.po_id_pk 
where cco.ct_id_pk = #{ct_id_pk};

select * from customer_info ci 
inner join customer_img ci2 on ci.ct_id_pk = ci2.ct_id_pk 
where ci.ct_id_pk = #{ct_id_pk};
